# Parse Claude API response
items = items or []
if not items:
    return [{"json": {"error": "No data"}}]

item = items[0].get('json', items[0])

# Extract the summary text
summary = ""
if isinstance(item, dict):
    for key in ['content', 'text', 'summary']:
        if key in item:
            val = item[key]
            if isinstance(val, list):
                for block in val:
                    if isinstance(block, dict) and block.get('type') == 'text':
                        summary = block.get('text', '')
                        break
                    elif isinstance(block, str):
                        summary = block
            elif isinstance(val, str):
                summary = val

# Build output
output = {
    "summary": summary,
    "generated_at": items[0].get('json', {}).get('generated_at', ''),
    "repo": items[0].get('json', {}).get('repo_name', ''),
    "week": f"{items[0].get('json', {}).get('week_start', '')} to {items[0].get('json', {}).get('week_end', '')}"
}

return [{"json": output}]
